import{_ as o,K as i,a as l,c as h,ac as t,b as a,q as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"English 音标","description":"英语元音、辅音及发音分类对照表","frontmatter":{"title":"English 音标","description":"英语元音、辅音及发音分类对照表","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/English/2023-05-17-3-phonetic_transcription.md","date":"Sat May 16 2020 12:12:56 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"英语基础","summary":"英语元音、辅音及发音分类对照表","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"English 简介","link":"/life/english/foundations/1-english"},"next":{"text":"English 词性","link":"/life/english/foundations/4-part_of_speech"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"English 简介","link":"/life/english/foundations/1-english"},"next":{"text":"English 词性","link":"/life/english/foundations/4-part_of_speech"}},"headers":[],"relativePath":"life/english/foundations/3-phonetic_transcription.md","filePath":"life/english/foundations/3-phonetic_transcription.md"}'),d={name:"life/english/foundations/3-phonetic_transcription.md"};function s(b,e,f,y,p,c){const r=i("ArticleImage");return l(),h("div",null,[e[0]||(e[0]=t('<h1 id="english-音标" tabindex="-1">English 音标 <a class="header-anchor" href="#english-音标" aria-label="Permalink to &quot;English 音标&quot;">​</a></h1><h2 id="音标简介" tabindex="-1">音标简介 <a class="header-anchor" href="#音标简介" aria-label="Permalink to &quot;音标简介&quot;">​</a></h2><ol><li>国际音标（IPA）：是一套记录语音的符号系统，可用于英语及其他语言，包括辅音、元音符号和重音、音长等标记。它不是某一种英语口音。</li><li>RP（Received Pronunciation）：是英国英语的一种口音，曾广泛用作英语教学的发音参照；“英式音标”通常指词典对英式发音的记音，不能把所有英国口音都等同于 RP。</li><li>GA（General American）：是美国英语教学中常用的发音参照。RP 和 GA 都可以用 IPA 记录；两者在具体词的发音和记音习惯上有差异，并不是两套彼此独立的国际音标。</li></ol><h2 id="音标选择" tabindex="-1">音标选择 <a class="header-anchor" href="#音标选择" aria-label="Permalink to &quot;音标选择&quot;">​</a></h2><p>先看所用词典或教材说明采用哪一种发音参照，再配合同一口音的录音学习。查英式或美式发音时都可能看到 IPA；需要核对的是具体音值和词典的记音说明，而不是在“RP、GA、IPA”三者中选一套音标。</p><h2 id="音标基础" tabindex="-1">音标基础 <a class="header-anchor" href="#音标基础" aria-label="Permalink to &quot;音标基础&quot;">​</a></h2><ol><li><p>元音和辅音：英语语音通常分为元音和辅音。发元音时，气流通过声道时没有形成辅音那样的明显阻碍；发辅音时，声道某处形成闭塞或收窄。音标是记录这些音的符号。</p></li><li><p>发音位置与清浊：发音部位说明气流在哪里受到阻碍，清浊说明声带是否振动。清辅音发音时声带不振动，浊辅音发音时声带振动。例如 /t/ 和 /d/ 的发音部位相同，但前者是清辅音，后者是浊辅音；不能用舌头前后位置判断清浊。</p></li><li><p>音标符号：IPA 用符号及必要的附加标记记录语音。英语词典会选择适合所记口音的符号，并在发音指南中说明惯例；同一个词的英式和美式记音可能不同。</p></li><li><p>音标分类：音标可以根据不同的属性进行分类。例如，元音可以分为前、中和后三类，辅音可以根据发音部位和发音方法进行分类。</p></li><li><p>语音规则：学习音标还需要了解相关的语音规则。例如，元音的长度、强调和连读等都会影响单词和句子的发音。</p></li></ol><h2 id="字母分类-26" tabindex="-1">字母分类(26) <a class="header-anchor" href="#字母分类-26" aria-label="Permalink to &quot;字母分类(26)&quot;">​</a></h2><blockquote><p><strong>ABCDEFGHIJKLMNOPQRSTUVWXYZ</strong></p></blockquote><ul><li>元音(5)：A、E、I、O、U</li><li>辅音(21)：BCDFGHJKLMNPQRSTVWXYZ</li></ul><h2 id="音标分类-48" tabindex="-1">音标分类(48) <a class="header-anchor" href="#音标分类-48" aria-label="Permalink to &quot;音标分类(48)&quot;">​</a></h2><p>本节保留传统“48 项”教学表的标题：它按传统 RP 教学口径列出 20 个元音，并把 24 个辅音与 /tr/、/dr/、/ts/、/dz/ 四种辅音组合合计为 28 项。下方辅音主表只列 24 个音，四种组合另作说明；因此常见的“44 个音”（20 + 24）与这里的“48 项”计数对象不同。它们都不是完整 IPA 的符号总数，也不适用于所有英语口音。可对照<a href="https://fonetika.ff.cuni.cz/o-fonetice/foneticka-transkripce/ipa-transcription-english/" target="_blank" rel="noopener noreferrer">查理大学语音学研究所的英语 IPA 表</a>核对这 44 个音。</p><h3 id="元音参考地址" tabindex="-1">元音<a href="https://en-yinbiao.xiao84.com/study/24568.html" target="_blank" rel="noopener noreferrer">参考地址</a> <a class="header-anchor" href="#元音参考地址" aria-label="Permalink to &quot;元音[参考地址](https://en-yinbiao.xiao84.com/study/24568.html)&quot;">​</a></h3><blockquote><p>指发音时不受到发音器官的阻碍发出的声音</p></blockquote>',14)),a("p",null,[n(r,{src:"https://i.xiao84.com/en-yinbiao/211015/1-211015200R11I.gif",alt:"元音20个"})]),e[1]||(e[1]=t('<h3 id="元音发音" tabindex="-1">元音发音 <a class="header-anchor" href="#元音发音" aria-label="Permalink to &quot;元音发音&quot;">​</a></h3><blockquote><p>元音音标中单元音按发音时舌头位置的不同分为前元音、中元音和后元音，双元音按发音时舌位和口型的变化分为合口双元音和集中双元音</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">元音（20 个）</th><th style="text-align:center;"></th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24557.html" target="_blank" rel="noopener noreferrer">单元音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24554.html" target="_blank" rel="noopener noreferrer">前元音</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/i-sound2.html" target="_blank" rel="noopener noreferrer">/iː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/i-sound.html" target="_blank" rel="noopener noreferrer">/ɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/e-sound.html" target="_blank" rel="noopener noreferrer">/e/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/an-sound.html" target="_blank" rel="noopener noreferrer">/æ/</a></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24555.html" target="_blank" rel="noopener noreferrer">中元音</a></td><td style="text-align:center;"></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/er-sound.html" target="_blank" rel="noopener noreferrer">/ɜː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/e%5E-sound.html" target="_blank" rel="noopener noreferrer">/ə/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/%5E-sound.html" target="_blank" rel="noopener noreferrer">/ʌ/</a></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24556.html" target="_blank" rel="noopener noreferrer">后元音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/u-sound2.html" target="_blank" rel="noopener noreferrer">/uː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/u-sound.html" target="_blank" rel="noopener noreferrer">/ʊ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/o-sound2.html" target="_blank" rel="noopener noreferrer">/ɔː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/o-sound.html" target="_blank" rel="noopener noreferrer">/ɒ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/a-sound2.html" target="_blank" rel="noopener noreferrer">/ɑː/</a></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24560.html" target="_blank" rel="noopener noreferrer">双元音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24558.html" target="_blank" rel="noopener noreferrer">开合 双元音</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ei.html" target="_blank" rel="noopener noreferrer">/eɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ai.html" target="_blank" rel="noopener noreferrer">/aɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/oi.html" target="_blank" rel="noopener noreferrer">/ɔɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ao.html" target="_blank" rel="noopener noreferrer">/aʊ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/eu.html" target="_blank" rel="noopener noreferrer">/əʊ/</a></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24559.html" target="_blank" rel="noopener noreferrer">集中 双元音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ir.html" target="_blank" rel="noopener noreferrer">/ɪə/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/er.html" target="_blank" rel="noopener noreferrer">/eə/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/uer.html" target="_blank" rel="noopener noreferrer">/ʊə/</a></td><td></td><td></td><td></td></tr></tbody></table><h3 id="长短区分" tabindex="-1">长短区分 <a class="header-anchor" href="#长短区分" aria-label="Permalink to &quot;长短区分&quot;">​</a></h3><blockquote><p>元音音标中单元音按发音时音音长短的不同分为长元音、短元音，长元音音标符号包括“:”号</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">元音（20 个）</th><th style="text-align:center;"></th><th></th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td style="text-align:center;">单元音</td><td style="text-align:center;">长元音</td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/i-sound2.html" target="_blank" rel="noopener noreferrer">/iː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/u-sound2.html" target="_blank" rel="noopener noreferrer">/uː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/a-sound2.html" target="_blank" rel="noopener noreferrer">/ɑː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/o-sound2.html" target="_blank" rel="noopener noreferrer">/ɔː/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/er-sound.html" target="_blank" rel="noopener noreferrer">/ɜː/</a></td><td></td></tr><tr><td style="text-align:center;">短元音</td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/i-sound.html" target="_blank" rel="noopener noreferrer">/ɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/u-sound.html" target="_blank" rel="noopener noreferrer">/ʊ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/%5E-sound.html" target="_blank" rel="noopener noreferrer">/ʌ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/o-sound.html" target="_blank" rel="noopener noreferrer">/ɒ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/e%5E-sound.html" target="_blank" rel="noopener noreferrer">/ə/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/e-sound.html" target="_blank" rel="noopener noreferrer">/e/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/an-sound.html" target="_blank" rel="noopener noreferrer">/æ/</a></td></tr><tr><td style="text-align:center;">双元音</td><td style="text-align:center;">合口双元音</td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ai.html" target="_blank" rel="noopener noreferrer">/aɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ei.html" target="_blank" rel="noopener noreferrer">/eɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/oi.html" target="_blank" rel="noopener noreferrer">/ɔɪ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ao.html" target="_blank" rel="noopener noreferrer">/aʊ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/eu.html" target="_blank" rel="noopener noreferrer">/əʊ/</a></td><td></td></tr><tr><td style="text-align:center;">集中双元音</td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ir.html" target="_blank" rel="noopener noreferrer">/ɪə/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/er.html" target="_blank" rel="noopener noreferrer">/eə/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/uer.html" target="_blank" rel="noopener noreferrer">/ʊə/</a></td><td></td><td></td><td></td><td></td></tr></tbody></table><h4 id="辅音参考地址" tabindex="-1">辅音<a href="https://en-yinbiao.xiao84.com/study/24569.html" target="_blank" rel="noopener noreferrer">参考地址</a> <a class="header-anchor" href="#辅音参考地址" aria-label="Permalink to &quot;辅音[参考地址](https://en-yinbiao.xiao84.com/study/24569.html)&quot;">​</a></h4><blockquote><ul><li>辅音又叫子音，发音时声道某处形成闭塞或收窄；是否为浊辅音取决于声带是否振动，不能用“是否响亮”判断。</li><li>本文辅音主表列 24 个音；旧教学图中的 28 项还包括四种辅音组合，不能据此认为英语有 28 个独立辅音。</li></ul></blockquote>',8)),a("p",null,[n(r,{src:"https://i.xiao84.com/allimg/150711/1-150G1143HO29.gif",alt:"辅音音标"})]),e[2]||(e[2]=t('<p>旧图沿用传统 28 项分组；下表按 24 个辅音列示，/r/ 的归类及四种组合以下文说明为准。</p><h3 id="辅音说明" tabindex="-1">辅音说明 <a class="header-anchor" href="#辅音说明" aria-label="Permalink to &quot;辅音说明&quot;">​</a></h3><ul><li>辅音音标根据发音时声带是否振动分为清辅音和浊辅音；</li><li>根据发音方式分为爆破音、摩擦音、破擦音、鼻音和近音等；/l/ 是舌侧近音，/j/、/w/ 常称半元音；</li><li>根据使用的发音部位分为双唇音、唇齿音、上腭音、舌齿音、软腭音和声门音</li><li>辅音发音时声道形成不同程度的阻碍，近音的收窄程度较小，不产生摩擦音那样的摩擦。</li><li>辅音通常与元音一起构成音节，但在某些非重读音节中，/n/、/l/ 等可作音节核心。例如 button 可读作 [ˈbʌtn̩]，little 可读作 [ˈlɪtl̩]，末尾辅音下的竖线表示成音节。这不表示任意辅音组合都能构成音节；有些口音或读法仍保留 /ə/。</li></ul><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24569.html" target="_blank" rel="noopener noreferrer">辅音</a></th><th style="text-align:center;"></th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24567.html" target="_blank" rel="noopener noreferrer">爆破音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24561.html" target="_blank" rel="noopener noreferrer">清辅音</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/p.html" target="_blank" rel="noopener noreferrer">/p/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/t.html" target="_blank" rel="noopener noreferrer">/t/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/k.html" target="_blank" rel="noopener noreferrer">/k/</a></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24562.html" target="_blank" rel="noopener noreferrer">浊辅音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/b.html" target="_blank" rel="noopener noreferrer">/b/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/d.html" target="_blank" rel="noopener noreferrer">/d/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/g.html" target="_blank" rel="noopener noreferrer">/ɡ/</a></td><td></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24566.html" target="_blank" rel="noopener noreferrer">摩擦音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24561.html" target="_blank" rel="noopener noreferrer">清辅音</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/f.html" target="_blank" rel="noopener noreferrer">/f/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/s.html" target="_blank" rel="noopener noreferrer">/s/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ss.html" target="_blank" rel="noopener noreferrer">/ʃ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/si.html" target="_blank" rel="noopener noreferrer">/θ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/h.html" target="_blank" rel="noopener noreferrer">/h/</a></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24562.html" target="_blank" rel="noopener noreferrer">浊辅音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/v.html" target="_blank" rel="noopener noreferrer">/v/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/z.html" target="_blank" rel="noopener noreferrer">/z/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/n3.html" target="_blank" rel="noopener noreferrer">/ʒ/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/qq.html" target="_blank" rel="noopener noreferrer">/ð/</a></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24565.html" target="_blank" rel="noopener noreferrer">破擦音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24561.html" target="_blank" rel="noopener noreferrer">清辅音</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/tss.html" target="_blank" rel="noopener noreferrer">/tʃ/</a></td><td></td><td></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24562.html" target="_blank" rel="noopener noreferrer">浊辅音</a></td><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/d3.html" target="_blank" rel="noopener noreferrer">/dʒ/</a></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/27874.html" target="_blank" rel="noopener noreferrer">鼻音</a></td><td style="text-align:center;">浊辅音</td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/m.html" target="_blank" rel="noopener noreferrer">/m/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/n.html" target="_blank" rel="noopener noreferrer">/n/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ng.html" target="_blank" rel="noopener noreferrer">/ŋ/</a></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24564.html" target="_blank" rel="noopener noreferrer">舌侧音</a></td><td style="text-align:center;">浊辅音</td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/l.html" target="_blank" rel="noopener noreferrer">/l/</a></td><td></td><td></td><td></td><td></td></tr><tr><td style="text-align:center;"><a href="https://en-yinbiao.xiao84.com/study/24563.html" target="_blank" rel="noopener noreferrer">半元音</a></td><td style="text-align:center;">浊辅音</td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/j.html" target="_blank" rel="noopener noreferrer">/j/</a></td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/w.html" target="_blank" rel="noopener noreferrer">/w/</a></td><td></td><td></td><td></td></tr><tr><td style="text-align:center;">近音</td><td style="text-align:center;">浊辅音</td><td><a href="https://en-yinbiao.xiao84.com/yinbiaofayin/r.html" target="_blank" rel="noopener noreferrer">/r/</a></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>这里沿用英语词典常用的 /r/ 记号；它在 RP 等口音中通常实现为近音 [ɹ]，不列作摩擦音。IPA 中 [r] 本身表示颤音，要区分词典的宽式记音惯例与具体音值。</p><p>传统表另外列出的 <a href="https://en-yinbiao.xiao84.com/yinbiaofayin/tr.html" target="_blank" rel="noopener noreferrer">/tr/</a>、<a href="https://en-yinbiao.xiao84.com/yinbiaofayin/dr.html" target="_blank" rel="noopener noreferrer">/dr/</a>、<a href="https://en-yinbiao.xiao84.com/yinbiaofayin/ts.html" target="_blank" rel="noopener noreferrer">/ts/</a>、<a href="https://en-yinbiao.xiao84.com/yinbiaofayin/dz.html" target="_blank" rel="noopener noreferrer">/dz/</a> 在这里按辅音组合处理，不增加主表的音素数；/tʃ/ 和 /dʒ/ 则是主表中的两个破擦音。</p><h3 id="元音和辅音区别" tabindex="-1">元音和辅音区别 <a class="header-anchor" href="#元音和辅音区别" aria-label="Permalink to &quot;元音和辅音区别&quot;">​</a></h3><ul><li>元音和辅音是语音的分类，台湾地区也称母音和子音；音标是记录语音的符号。</li><li>英语元音通常伴随声带振动，声道没有辅音那样的闭塞或明显收窄，通常充当音节核心。</li><li>辅音可清可浊：清辅音声带不振动，浊辅音声带振动；气流的阻碍部位和方式则是另外的分类维度。不能用响度、气流强弱或舌头前后位置代替清浊判断。</li><li>辅音通常处于元音前后；在上文 button、little 等词的某些读法中，成音节辅音也能充当音节核心。/m/ 以及某些口音中的 /r/ 也有成音节读法，不能把例外限定为一份适用于所有口音的固定清单。</li></ul><h3 id="音标全部" tabindex="-1">音标全部 <a class="header-anchor" href="#音标全部" aria-label="Permalink to &quot;音标全部&quot;">​</a></h3><p>完整符号已分别列在上文的元音发音、长短区分和辅音说明中，按发音类别查阅即可。</p><p>记音与发音分类可查<a href="https://www.internationalphoneticassociation.org/IPAcharts/IPA_charts_TI/IPA_charts_TI.html" target="_blank" rel="noopener noreferrer">国际语音学会 IPA 图表</a>；成音节辅音参见<a href="https://www.oxfordlearnersdictionaries.com/about/english/pronunciation_english" target="_blank" rel="noopener noreferrer">牛津学习词典发音指南</a>。</p>',12))])}const x=o(d,[["render",s]]);export{g as __pageData,x as default};
